create table if not exists public.contracts(id bigint generated always as identity primary key,organization_id uuid not null default current_organization_id() references organizations(id) on delete cascade,title text not null,vendor text,status text default 'active',starts_on date,ends_on date,value numeric default 0,department text,created_at timestamptz not null default now());
create table if not exists public.activities(id bigint generated always as identity primary key,organization_id uuid not null default current_organization_id() references organizations(id) on delete cascade,action text not null,subject text,department text,actor_id uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.export_history(id bigint generated always as identity primary key,organization_id uuid not null default current_organization_id() references organizations(id) on delete cascade,file_name text not null,file_type text not null check(file_type in('xlsx','pdf','csv')),source text not null,record_count integer not null default 0,file_size bigint,filters jsonb not null default '{}'::jsonb,exported_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.member_export_permissions(organization_id uuid not null,user_id uuid not null,can_export_excel boolean not null default false,can_export_pdf boolean not null default false,can_export_financial boolean not null default false,updated_at timestamptz not null default now(),primary key(organization_id,user_id),foreign key(organization_id,user_id) references organization_members(organization_id,user_id) on delete cascade);
create table if not exists public.scheduled_reports(id uuid primary key default gen_random_uuid(),organization_id uuid not null default current_organization_id() references organizations(id) on delete cascade,name text not null,source text not null,format text not null check(format in('xlsx','pdf','csv')),frequency text not null check(frequency in('daily','weekly','monthly')),recipients text[] not null,filters jsonb not null default '{}'::jsonb,next_run_at timestamptz,status text not null default 'active',created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
alter table contracts enable row level security;alter table activities enable row level security;alter table export_history enable row level security;alter table member_export_permissions enable row level security;alter table scheduled_reports enable row level security;
drop policy if exists tenant_contracts on contracts;create policy tenant_contracts on contracts for all to authenticated using(organization_id=current_organization_id() and has_section_access('contracts')) with check(organization_id=current_organization_id() and has_section_access('contracts'));
drop policy if exists tenant_activities on activities;create policy tenant_activities on activities for select to authenticated using(organization_id=current_organization_id() and has_section_access('operations'));
drop policy if exists tenant_export_history_read on export_history;create policy tenant_export_history_read on export_history for select to authenticated using(organization_id=current_organization_id() and has_section_access('reports'));
drop policy if exists tenant_export_history_insert on export_history;create policy tenant_export_history_insert on export_history for insert to authenticated with check(organization_id=current_organization_id() and exported_by=auth.uid() and has_section_access('reports'));
drop policy if exists tenant_export_permissions on member_export_permissions;create policy tenant_export_permissions on member_export_permissions for select to authenticated using(organization_id=current_organization_id());
drop policy if exists tenant_export_permissions_admin on member_export_permissions;create policy tenant_export_permissions_admin on member_export_permissions for all to authenticated using(is_company_admin(organization_id)) with check(is_company_admin(organization_id));
drop policy if exists tenant_schedules on scheduled_reports;create policy tenant_schedules on scheduled_reports for all to authenticated using(organization_id=current_organization_id() and is_company_admin()) with check(organization_id=current_organization_id() and is_company_admin());
grant select,insert,update,delete on contracts,activities,export_history,member_export_permissions,scheduled_reports to authenticated;
create or replace function public.get_my_export_permissions() returns jsonb language sql stable security definer set search_path=public as $$ select case when is_company_admin() then '{"xlsx":true,"pdf":true,"financial":true}'::jsonb else jsonb_build_object('xlsx',coalesce(p.can_export_excel,false),'pdf',coalesce(p.can_export_pdf,false),'financial',coalesce(p.can_export_financial,false)) end from (select 1) x left join member_export_permissions p on p.organization_id=current_organization_id() and p.user_id=auth.uid() $$;
grant execute on function public.get_my_export_permissions() to authenticated;
